sql.where:
tc.status = 'AVAILABLE'
AND tc.semester_id = #{requestParam.semesterId}
AND tc.semester_id IN (SELECT id FROM semester WHERE status = 'ACTIVE')
AND EXISTS (
SELECT 1 FROM selection_batch_class sbc
WHERE sbc.batch_id = #{requestParam.batchId} AND sbc.teaching_class_id = tc.id
)
AND EXISTS (
SELECT 1 FROM teaching_class_major tcm
WHERE tcm.teaching_class_id = tc.id AND tcm.major_id = #{requestParam.majorId}
)
AND EXISTS (
SELECT 1 FROM teaching_class_grade tcg
WHERE tcg.teaching_class_id = tc.id AND tcg.grade_id = #{requestParam.gradeId}
)
AND c.status = 1

    AND c.course_type = #{requestParam.courseType}


    AND (c.course_name LIKE CONCAT('%', #{requestParam.keyword}, '%')
    OR c.course_code LIKE CONCAT('%', #{requestParam.keyword}, '%')
    OR t.teacher_name LIKE CONCAT('%', #{requestParam.keyword}, '%'))


    AND EXISTS (
    SELECT 1 FROM teaching_class_schedule tcs
    WHERE tcs.teaching_class_id = tc.id AND tcs.weekday = #{requestParam.weekday}
    )
